const ProceduralMap: React.FC<{
  countryCode: string;
  frame: number;
  fps: number;
  accentColor: string;
}> = ({ countryCode, frame, fps, accentColor }) => {
  const code = countryCode.toUpperCase();
  const data = COUNTRY_DATA[code];
  const theme = COUNTRY_THEMES[code];
  if (!data || !theme) return null;

  const drawSpring = spring({
    frame: Math.max(0, frame - 10),
    fps,
    config: { damping: 25, stiffness: 45 },
  });

  const fillProgress = interpolate(frame, [25, 55], [0, 0.9], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const radarPulse = (frame % 45) / 45;
  const radarRadius = 15 + radarPulse * 65;
  const radarOpacity = 1 - radarPulse;

  const vbParts = data.viewBox.split(" ").map(parseFloat);
  const centerX = vbParts[0] + vbParts[2] / 2;
  const centerY = vbParts[1] + vbParts[3] / 2;

  const gradientId = `flag-grad-${code}`;

  return (
    <div style={{
      position: "relative",
      width: "100%",
      height: "100%",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      overflow: "hidden",
    }}>
      <div style={{
        position: "absolute",
        bottom: "8%",
        right: "8%",
        fontFamily: "'Oswald', sans-serif",
        fontSize: 120,
        fontWeight: 900,
        color: "rgba(0,0,0,0.04)",
        letterSpacing: "0.05em",
        pointerEvents: "none",
        userSelect: "none",
        zIndex: 0,
      }}>
        {theme.name}
      </div>

      <svg
        viewBox={data.viewBox}
        style={{
          width: "80%",
          height: "80%",
          maxHeight: "80%",
          filter: "drop-shadow(0 20px 40px rgba(0,0,0,0.45))",
          overflow: "visible",
          zIndex: 1,
        }}
      >
        <defs>
          <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={theme.primary} stopOpacity={fillProgress} />
            <stop offset="100%" stopColor={theme.secondary} stopOpacity={fillProgress} />
          </linearGradient>
        </defs>

        {data.paths.map((p, idx) => (
          <path
            key={idx}
            d={p}
            fill={`url(#${gradientId})`}
            stroke={accentColor}
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray="2000"
            strokeDashoffset={2000 * (1 - drawSpring)}
          />
        ))}

        {drawSpring > 0.8 && (
          <>
            <circle
              cx={centerX}
              cy={centerY}
              r={radarRadius}
              fill="none"
              stroke={accentColor}
              strokeWidth="2"
              opacity={radarOpacity * 0.7}
            />
            <circle
              cx={centerX}
              cy={centerY}
              r="4"
              fill={accentColor}
              opacity={0.9}
            />
            <line x1={centerX - 12} y1={centerY} x2={centerX + 12} y2={centerY} stroke={accentColor} strokeWidth="1" opacity={0.6} />
            <line x1={centerX} y1={centerY - 12} x2={centerX} y2={centerY + 12} stroke={accentColor} strokeWidth="1" opacity={0.6} />
          </>
        )}
      </svg>
    </div>
  );
};

