const ProceduralAssetOrbit: React.FC<{
  keywords: string[];
  frame: number;
  fps: number;
  accentColor: string;
  assetSide: "left" | "right";
  entranceDelay: number;
}> = ({ keywords, frame, fps, accentColor, assetSide, entranceDelay }) => {
  if (!keywords || keywords.length === 0) return null;

  const positions: Array<{ top: string; left?: string; right?: string; delay: number; rotate: number }> = [
    { top: "16%", ...(assetSide === "right" ? { left: "6%" } : { right: "6%" }), delay: 0,  rotate: -8 },
    { top: "42%", ...(assetSide === "right" ? { left: "4%" } : { right: "4%" }), delay: 8,  rotate:  5 },
    { top: "66%", ...(assetSide === "right" ? { left: "7%" } : { right: "7%" }), delay: 16, rotate: -4 },
  ];

  return (
    <>
      {keywords.slice(0, 3).map((kw, i) => {
        const pos = positions[i] || positions[0];
        const localDelay = entranceDelay + pos.delay;
        const entryProgress = spring({
          frame: Math.max(0, frame - localDelay),
          fps,
          config: { damping: 14, stiffness: 90 },
        });
        const floatY = Math.sin(frame / 35 + i * 1.5) * 8;
        const floatRotate = Math.cos(frame / 48 + i * 1.1) * 3;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              top: pos.top,
              left: pos.left,
              right: pos.right,
              zIndex: 6,
              opacity: entryProgress * 0.9,
              transform: `
                translateY(${interpolate(entryProgress, [0, 1], [-80, 0]) + floatY}px)
                scale(${entryProgress})
                rotate(${pos.rotate + floatRotate}deg)
              `,
              padding: "16px",
              background: "rgba(10, 15, 26, 0.75)",
              backdropFilter: "blur(8px)",
              borderRadius: "12px",
              border: `2px dashed ${accentColor}50`,
              boxShadow: "0 10px 30px rgba(0,0,0,0.55)",
            }}
          >
            <ProceduralIcon type={kw} size={56} color={accentColor} />
          </div>
        );
      })}
    </>
  );
};

const DramaticSilhouette: React.FC<{
  frame: number;
  fps: number;
  accentColor: string;
  personName?: string;
}> = ({ frame, fps, accentColor, personName }) => {
  const drawSpring = spring({
    frame: Math.max(0, frame - 15),
    fps,
    config: { damping: 15, stiffness: 90 },
  });

  const nameText = (personName || "AGENTE").toUpperCase();
  const rimLightGlowId = `rim-glow-${nameText.replace(/\s+/g, "")}`;

  const nodes = [
    { cx: 270, cy: 110 },
    { cx: 245, cy: 155 },
    { cx: 295, cy: 155 },
    { cx: 270, cy: 175 },
    { cx: 270, cy: 205 },
    { cx: 235, cy: 230 },
    { cx: 305, cy: 230 },
  ];

  return (
    <div style={{
      position: "relative",
      width: "100%",
      height: "100%",
      display: "flex",
      justifyContent: "center",
      alignItems: "flex-end",
    }}>
      <div style={{
        position: "absolute",
        left: "5%",
        bottom: "10%",
        fontFamily: "'Oswald', sans-serif",
        fontSize: 110,
        fontWeight: 900,
        color: "rgba(255, 255, 255, 0.05)",
        transform: "rotate(-90deg)",
        transformOrigin: "left bottom",
        whiteSpace: "nowrap",
        letterSpacing: "0.08em",
        pointerEvents: "none",
        zIndex: 0,
      }}>
        {nameText}
      </div>

      <svg
        viewBox="0 0 540 540"
        style={{
          width: "80%",
          height: "90%",
          overflow: "visible",
          zIndex: 1,
        }}
      >
        <defs>
          <filter id={rimLightGlowId} x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur in="SourceAlpha" stdDeviation="15" result="blur" />
            <feComponentTransfer in="blur" result="glow">
              <feFuncA type="linear" slope="1.8" />
            </feComponentTransfer>
            <feMerge>
              <feMergeNode in="glow" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        <g filter={`url(#${rimLightGlowId})`}>
          <path
            d="M 120 540 C 120 440, 160 400, 200 370 C 180 340, 185 270, 200 250 C 190 230, 190 120, 270 80 C 350 120, 350 230, 340 250 C 355 270, 360 340, 340 370 C 380 400, 420 440, 420 540 Z"
            fill="#0b0f19"
            stroke={accentColor}
            strokeWidth="4.5"
            strokeLinejoin="round"
          />
        </g>

        {drawSpring > 0.4 && (
          <g opacity={drawSpring * 0.8}>
            <circle cx="270" cy="170" r="110" fill="none" stroke={accentColor} strokeWidth="1.5" strokeDasharray="8 8" opacity="0.4" />
            
            <path d="M 180 100 L 160 100 L 160 120" fill="none" stroke={accentColor} strokeWidth="2.5" />
            <path d="M 360 100 L 380 100 L 380 120" fill="none" stroke={accentColor} strokeWidth="2.5" />
            <path d="M 180 240 L 160 240 L 160 220" fill="none" stroke={accentColor} strokeWidth="2.5" />
            <path d="M 360 240 L 380 240 L 380 220" fill="none" stroke={accentColor} strokeWidth="2.5" />

            <line
              x1="180"
              y1={100 + (140 * ((frame % 60) / 60))}
              x2="360"
              y2={100 + (140 * ((frame % 60) / 60))}
              stroke={accentColor}
              strokeWidth="2"
              opacity="0.8"
            />

            <path
              d="M 270 110 L 245 155 L 270 175 L 270 110 M 270 110 L 295 155 L 270 175 M 245 155 L 235 230 L 270 205 L 295 155 L 305 230 L 270 205 M 270 175 L 270 205"
              fill="none"
              stroke={accentColor}
              strokeWidth="1"
              opacity="0.5"
            />

            {nodes.map((node, i) => (
              <circle key={i} cx={node.cx} cy={node.cy} r="4.5" fill={accentColor} stroke="#0b0f19" strokeWidth="1.5" />
            ))}

            <text x="395" y="115" fontFamily="'Oswald', sans-serif" fontSize="12" fill={accentColor} letterSpacing="0.1em" fontWeight="bold">
              ID: DETECTADO
            </text>
            <text x="395" y="135" fontFamily="'Oswald', sans-serif" fontSize="11" fill="rgba(255,255,255,0.7)" letterSpacing="0.1em">
              MATCH: 98.4%
            </text>
          </g>
        )}
      </svg>
    </div>
  );
};

const ProceduralComparison: React.FC<{
  frame: number;
  fps: number;
  accentColor: string;
  mapCountry?: string | null;
  comparisonCountry?: string | null;
  brandDomain?: string | null;
  comparisonBrandDomain?: string | null;
  headline?: string;
  subtext?: string;
}> = ({ frame, fps, accentColor, mapCountry, comparisonCountry, brandDomain, comparisonBrandDomain, headline, subtext }) => {
  const slideA = spring({ frame, fps, config: { damping: 16, stiffness: 100 } });
  const slideB = spring({ frame: Math.max(0, frame - 4), fps, config: { damping: 16, stiffness: 100 } });

  const sideA = useMemo(() => {
    if (mapCountry) return { type: "country" as const, code: mapCountry.toUpperCase() };
    if (brandDomain) return { type: "brand" as const, domain: brandDomain };
    return { type: "country" as const, code: "CN" };
  }, [mapCountry, brandDomain]);

  const sideB = useMemo(() => {
    if (comparisonCountry) return { type: "country" as const, code: comparisonCountry.toUpperCase() };
    if (comparisonBrandDomain) return { type: "brand" as const, domain: comparisonBrandDomain };
    return { type: "country" as const, code: "US" };
  }, [comparisonCountry, comparisonBrandDomain]);

  const metrics = useMemo(() => {
    const text = `${headline ?? ""} ${subtext ?? ""}`;
    const matches = [...text.matchAll(/(-?\d+(?:[.,]\d+)?)/g)].map(m => parseFloat(m[1].replace(",", ".")));
    if (matches.length >= 2) {
      return { valA: matches[0], valB: matches[1], label: "INDICADOR COMPARATIVO" };
    }
    return { valA: 78, valB: 54, label: "MÉTRICA DE MERCADO" };
  }, [headline, subtext]);

  const maxVal = Math.max(Math.abs(metrics.valA), Math.abs(metrics.valB), 1);
  const percentA = Math.min(100, Math.max(10, (Math.abs(metrics.valA) / maxVal) * 100));
  const percentB = Math.min(100, Math.max(10, (Math.abs(metrics.valB) / maxVal) * 100));

  const drawMeterA = spring({ frame: Math.max(0, frame - 18), fps, config: { damping: 15, stiffness: 90 } });
  const drawMeterB = spring({ frame: Math.max(0, frame - 22), fps, config: { damping: 15, stiffness: 90 } });

  const renderSideContent = (side: typeof sideA, isRight: boolean) => {
    if (side.type === "country") {
      const code = side.code;
      const data = COUNTRY_DATA[code];
      const theme = COUNTRY_THEMES[code];
      if (!data || !theme) return null;

      const gradientId = `split-grad-${code}-${isRight ? "right" : "left"}`;

      return (
        <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          width: "100%",
          height: "100%",
          justifyContent: "center",
          gap: 16,
          padding: "60px 20px 100px",
        }}>
          <div style={{
            width: 80,
            height: 48,
            borderRadius: 6,
            overflow: "hidden",
            boxShadow: "0 8px 16px rgba(0,0,0,0.4)",
            border: "1.5px solid rgba(255,255,255,0.2)",
          }}>
            <img src={`https://flagcdn.com/w160/${code.toLowerCase()}.png`} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </div>

          <span style={{
            fontFamily: "'Oswald', sans-serif",
            fontSize: 32,
            fontWeight: 900,
            color: "#FFFFFF",
            letterSpacing: "0.06em",
          }}>
            {theme.name}
          </span>

          <svg
            viewBox={data.viewBox}
            style={{
              width: "70%",
              height: "180px",
              filter: `drop-shadow(0 15px 30px ${theme.primary}30)`,
              marginTop: 10,
              overflow: "visible",
            }}
          >
            <defs>
              <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor={theme.primary} />
                <stop offset="100%" stopColor={theme.secondary} />
              </linearGradient>
            </defs>
            {data.paths.map((p, idx) => (
              <path key={idx} d={p} fill={`url(#${gradientId})`} stroke={accentColor} strokeWidth="2.5" />
            ))}
          </svg>
        </div>
      );
    } else {
      const domain = side.domain;
      const initials = domain.split(".")[0].substring(0, 2).toUpperCase();
      return (
        <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          width: "100%",
          height: "100%",
          justifyContent: "center",
          gap: 20,
          padding: "60px 20px 100px",
        }}>
          <div style={{
            width: 100,
            height: 100,
            borderRadius: "50%",
            backgroundColor: "rgba(255,255,255,0.08)",
            border: `2px solid ${accentColor}`,
            boxShadow: `0 0 25px ${accentColor}30`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontSize: 32,
            fontFamily: "'Oswald', sans-serif",
            fontWeight: 900,
            color: accentColor,
            overflow: "hidden",
          }}>
            <img
              src={`https://logo.clearbit.com/${domain}`}
              style={{ width: "80%", height: "80%", objectFit: "contain" }}
              onError={(e) => { e.currentTarget.style.display = "none"; }}
            />
            {initials}
          </div>

          <span style={{
            fontFamily: "'Oswald', sans-serif",
            fontSize: 26,
            fontWeight: 900,
            color: "#FFFFFF",
            letterSpacing: "0.04em",
            textTransform: "uppercase",
          }}>
            {domain}
          </span>
        </div>
      );
    }
  };

  const transformA = `translateX(${interpolate(slideA, [0, 1], [-100, 0])}%)`;
  const transformB = `translateX(${interpolate(slideB, [0, 1], [100, 0])}%)`;

  return (
    <AbsoluteFill style={{ display: "flex", flexDirection: "row", background: "#0a0c14", overflow: "hidden" }}>
      <div style={{
        width: "50%",
        height: "100%",
        borderRight: `1px solid ${accentColor}50`,
        transform: transformA,
        background: "linear-gradient(to right, rgba(0,0,0,0.5) 0%, transparent 100%)",
      }}>
        {renderSideContent(sideA, false)}
      </div>

      <div style={{
        width: "50%",
        height: "100%",
        borderLeft: `1px solid ${accentColor}50`,
        transform: transformB,
        background: "linear-gradient(to left, rgba(0,0,0,0.5) 0%, transparent 100%)",
      }}>
        {renderSideContent(sideB, true)}
      </div>

      <div style={{
        position: "absolute",
        top: 0, bottom: 0,
        left: "50%",
        transform: "translateX(-50%)",
        width: 4,
        background: `repeating-linear-gradient(to bottom, transparent, transparent 15px, ${accentColor} 15px, ${accentColor} 30px)`,
        zIndex: 5,
      }} />

      <div style={{
        position: "absolute",
        bottom: "8%",
        left: "8%",
        right: "8%",
        height: 140,
        background: "rgba(0,0,0,0.65)",
        backdropFilter: "blur(10px)",
        borderRadius: 12,
        border: "1.5px solid rgba(255,255,255,0.1)",
        padding: "16px 24px",
        display: "flex",
        flexDirection: "column",
        justifyContent: "space-between",
        zIndex: 10,
        opacity: slideB,
      }}>
        <div style={{
          fontFamily: "'Oswald', sans-serif",
          fontSize: 14,
          fontWeight: 900,
          color: accentColor,
          letterSpacing: "0.08em",
          textAlign: "center",
        }}>
          {metrics.label}
        </div>

        <div style={{ display: "flex", alignItems: "center", width: "100%", gap: 20 }}>
          <div style={{ width: "50%", display: "flex", flexDirection: "column", alignItems: "flex-end" }}>
            <span style={{ fontFamily: "'Oswald', sans-serif", fontSize: 24, fontWeight: 900, color: "#FFFFFF" }}>
              {metrics.valA}
            </span>
            <div style={{ width: "100%", height: 16, background: "rgba(255,255,255,0.1)", borderRadius: 4, overflow: "hidden", display: "flex", justifyContent: "flex-end" }}>
              <div style={{
                width: `${percentA * drawMeterA}%`,
                height: "100%",
                background: accentColor,
                boxShadow: `0 0 10px ${accentColor}`,
              }} />
            </div>
          </div>

          <div style={{ width: "50%", display: "flex", flexDirection: "column", alignItems: "flex-start" }}>
            <span style={{ fontFamily: "'Oswald', sans-serif", fontSize: 24, fontWeight: 900, color: "#FFFFFF" }}>
              {metrics.valB}
            </span>
            <div style={{ width: "100%", height: 16, background: "rgba(255,255,255,0.1)", borderRadius: 4, overflow: "hidden" }}>
              <div style={{
                width: `${percentB * drawMeterB}%`,
                height: "100%",
                background: accentColor,
                boxShadow: `0 0 10px ${accentColor}`,
              }} />
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

